const indexes: Record<Locale, number> = { en: 1, nl: 2, pt: 3, ro: 4, fr: 5, fa: 6, ps: 7 }
const dictionary = new Map<string, Partial<Record<Locale, string>>>()
for (const row of rows) {
  const [source, ...values] = row
  if (!source) continue
  const item: Partial<Record<Locale, string>> = {}
  locales.forEach((locale) => {
    const value = values[indexes[locale] - 1]
    if (value) item[locale] = value
  })
  dictionary.set(source, item)
}

export function translate(text: string, locale: Locale): string {
  const leading = text.match(/^\s*/)?.[0] ?? ''
  const trailing = text.match(/\s*$/)?.[0] ?? ''
  const clean = text.trim()
  const translated = dictionary.get(clean)?.[locale]
  return translated ? `${leading}${translated}${trailing}` : text
}

export function isLocale(value: string): value is Locale {
  return locales.includes(value as Locale)
}
